@Test
public void testUnionQueries() throws Exception {
    Configuration conf = LensServerAPITestUtil.getConfigurationWithParams(getConf(), CubeQueryConfUtil.DRIVER_SUPPORTED_STORAGES, "C6", getValidFactTablesKey("basecube"), "testfact", FAIL_QUERY_ON_PARTIAL_DATA, false);
