    try {
        // Union query
        String hqlQuery;
        String expected;
        StoragePartitionProvider provider = new StoragePartitionProvider() {

            @Override
            public Map<String, String> providePartitionsForStorage(String storage) {
                if (storage.contains("daily_c6_testfact")) {
                    return getWhereForDays(storage, ONE_MONTH_BACK_TRUNCATED, getTruncatedDateWithOffset(MONTHLY, 0));
                } else if (storage.contains("monthly_c6_testfact")) {
                    return getWhereForMonthly(storage, THREE_MONTHS_BACK_TRUNCATED, ONE_MONTH_BACK_TRUNCATED);
                }
                return null;
            }
        };
        hqlQuery = rewrite("select cityname1 as `City Name`, msr8, msr7 as `Third measure` " + "from testCube where cityname1 = 'a' and zipcode = 'b' and " + THREE_MONTHS_RANGE_UPTO_MONTH, conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT (testcube.alias0) as `City Name`, (sum((testcube.alias1)) + max((testcube.alias2))) " + "as `msr8`, case  when (sum((testcube.alias1)) = 0) then 0 else (sum((testcube.alias4)) / " + "sum((testcube.alias1))) end as `Third measure` ", null, "group by testcube.alias0", "SELECT (cubecity1.name) as `alias0`, sum((testcube.msr2)) as `alias1`, max((testcube.msr3)) " + "as `alias2`, sum(case  when ((testcube.cityid) = 'x') then (testcube.msr21) " + "else (testcube.msr22) end) as `alias4` ", " join " + getDbName() + "c6_citytable cubecity1 on testcube.cityid1 = cubecity1.id " + "and (cubecity1.dt = 'latest') ", "((cubecity1.name) = 'a') and ((testcube.zipcode) = 'b')", "group by (cubecity1.name)");
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select ascii(cityid) as `City ID`, msr8, msr7 as `Third measure` " + "from testCube where ascii(cityid) = 'c' and cityid = 'a' and zipcode = 'b' and " + THREE_MONTHS_RANGE_UPTO_MONTH, conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT (testcube.alias0) as `City ID`, (sum((testcube.alias1)) + max((testcube.alias2))) as `msr8`, " + "case  when (sum((testcube.alias1)) = 0) then 0 else (sum((testcube.alias4)) / sum((testcube.alias1))) " + "end as `Third measure`", null, "group by testcube.alias0", "SELECT ascii((testcube.cityid)) as `alias0`, sum((testcube.msr2)) as `alias1`, max((testcube.msr3)) " + "as `alias2`, sum(case  when ((testcube.cityid) = 'x') then (testcube.msr21) " + "else (testcube.msr22) end) as `alias4`", "ascii(testcube.cityid) = 'c' and testcube.cityid = 'a' and testcube.zipcode = 'b'", "group by ascii(testcube.cityid)");
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select cityid as `City ID`, msr8, msr7 as `Third measure` " + "from testCube where cityid = 'a' and zipcode = 'b' and " + THREE_MONTHS_RANGE_UPTO_MONTH, conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT (testcube.alias0) as `City ID`, (sum((testcube.alias1)) + max((testcube.alias2))) as `msr8`, " + "case  when (sum((testcube.alias1)) = 0) then 0 else (sum((testcube.alias4)) / sum((testcube.alias1)))" + " end as `Third measure`", null, "group by testcube.alias0", "SELECT (testcube.cityid) as `alias0`, sum((testcube.msr2)) as `alias1`, max((testcube.msr3)) as `alias2`, " + "sum(case  when ((testcube.cityid) = 'x') then (testcube.msr21) else (testcube.msr22) end) as `alias4`", "testcube.cityid = 'a' and testcube.zipcode = 'b'", "group by testcube.cityid");
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select cityid as `City ID`, msr3 as `Third measure` from testCube where " + THREE_MONTHS_RANGE_UPTO_MONTH + " having msr7 > 10", conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT testcube.alias0 as `City ID`, max(testcube.alias1) as `Third measure`", null, "group by testcube.alias0 having " + "(case when sum(testcube.alias2)=0 then 0 else sum(testcube.alias3)/sum(testcube.alias2) end > 10 )", "SELECT testcube.cityid as `alias0`, max(testcube.msr3) as `alias1`, " + "sum(testcube.msr2) as `alias2`, " + "sum(case when testcube.cityid='x' then testcube.msr21 else testcube.msr22 end) as `alias3`", null, "group by testcube.cityid");
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select cityid as `City ID`, msr3 as `Third measure` from testCube where " + THREE_MONTHS_RANGE_UPTO_MONTH + " having msr8 > 10", conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT testcube.alias0 as `City ID`, max(testcube.alias1) as `Third measure`", null, "GROUP BY testcube.alias0 " + "HAVING (sum(testcube.alias2) + max(testcube.alias1)) > 10 ", "SELECT testcube.cityid as `alias0`, max(testcube.msr3) as `alias1`, " + "sum(testcube.msr2)as `alias2`", null, "group by testcube.cityid");
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select msr3 as `Measure 3` from testCube where " + THREE_MONTHS_RANGE_UPTO_MONTH + " having msr2 > 10 and msr2 < 100", conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT max(testcube.alias0) as `Measure 3` ", null, " HAVING sum(testcube.alias1) > 10 and sum(testcube.alias1) < 100", "SELECT max(testcube.msr3) as `alias0`, sum(testcube.msr2) as `alias1`", null, null);
        compareQueries(hqlQuery, expected);
        hqlQuery = rewrite("select zipcode, cityid as `CityID`, msr3 as `Measure 3`, msr4, " + "SUM(msr2) as `Measure 2` from testCube where " + THREE_MONTHS_RANGE_UPTO_MONTH + " having msr4 > 10 order by cityid desc limit 5", conf);
        expected = getExpectedUnionQuery(TEST_CUBE_NAME, storages, provider, "SELECT (testcube.alias0) as `zipcode`, (testcube.alias1) as `City ID`, max((testcube.alias2)) " + "as `Measure 3`, count((testcube.alias3)) as `msr4`, sum((testcube.alias4)) as `Measure 2`", null, "group by testcube.alias0, testcube.alias1 " + " having count(testcube.alias3) > 10 order by cityid desc limit 5", "SELECT (testcube.zipcode) as `alias0`, (testcube.cityid) as `alias1`, max((testcube.msr3)) as `alias2`, " + "count((testcube.msr4)) as `alias3`, sum((testcube.msr2)) as `alias4`", null, "group by testcube.zipcode, testcube.cityid ");
        compareQueries(hqlQuery, expected);
        // Order by column with whitespace in alias should fail
        try {
            hqlQuery = rewrite("select zipcode, cityid as `City ID`, msr3 as `Measure 3`, msr4, " + "SUM(msr2) as `Measure 2` from testCube where " + THREE_MONTHS_RANGE_UPTO_MONTH + " having msr4 > 10 order by cityid desc limit 5", conf);
        } catch (LensException e) {
            assertEquals(e.getErrorCode(), LensCubeErrorCode.ORDERBY_ALIAS_CONTAINING_WHITESPACE.getLensErrorInfo().getErrorCode());
        }
    } finally {
        getStorageToUpdatePeriodMap().clear();
    }
}

