        ColumnarSQLRewriter rewriter = new ColumnarSQLRewriter();
        rewriter.init(conf);
        rewriter.ast = HQLParser.parseHQL(query, hconf);
        rewriter.query = query;
        rewriter.analyzeInternal(conf, hconf);
        // Rewrite
        rewriter.replaceWithUnderlyingStorage(hconf);
        String fromStringAfterRewrite = HQLParser.getString(rewriter.fromAST);
        log.info("fromStringAfterRewrite:{}", fromStringAfterRewrite);
        assertEquals(HQLParser.getString(rewriter.getSelectAST()).trim(), "(t1.id1), (t2.id2), (t3.id3)," + " (t1.name1), (t2.name2), (t3.name3), count(1)", "Found :" + HQLParser.getString(rewriter.getSelectAST()));
        assertEquals(HQLParser.getString(rewriter.getWhereAST()).trim(), "((t1.id1) = 100)", "Found: " + HQLParser.getString(rewriter.getWhereAST()));
        assertEquals(HQLParser.getString(rewriter.getGroupByAST()).trim(), "(t2.id2)", "Found: " + HQLParser.getString(rewriter.getGroupByAST()));
        assertEquals(HQLParser.getString(rewriter.getOrderByAST()).trim(), "t3.id3 asc", "Found: " + HQLParser.getString(rewriter.getOrderByAST()));
        assertEquals(HQLParser.getString(rewriter.getHavingAST()).trim(), "(count((t1.id1)) > 2)", "Found: " + HQLParser.getString(rewriter.getHavingAST()));
        assertTrue(fromStringAfterRewrite.contains("(t1.t2id) = (t2.id2)") && fromStringAfterRewrite.contains("(t2.t3id) = (t3.id3)"), fromStringAfterRewrite);
        assertFalse(fromStringAfterRewrite.contains(testDB), fromStringAfterRewrite);
        assertTrue(fromStringAfterRewrite.contains("testdb"), fromStringAfterRewrite);
        assertTrue(fromStringAfterRewrite.contains("testtable_1") && fromStringAfterRewrite.contains("testtable_2") && fromStringAfterRewrite.contains("testtable_3"), fromStringAfterRewrite);
    } finally {
        Hive.get().dropTable("default", "mytable_3", true, true);
        Hive.get().dropDatabase(testDB, true, true, true);
        SessionState.get().setCurrentDatabase("default");
    }
}

/**
 * Test get connection hsql.
 *
 * @throws Exception the exception
 */
@Test
public void testGetConnectionHSQL() throws Exception {
    final Configuration conf = new Configuration();
    conf.set(JDBCDriverConfConstants.JDBC_DRIVER_CLASS, "org.hsqldb.jdbc.JDBCDriver");
    conf.set(JDBCDriverConfConstants.JDBC_DB_URI, "jdbc:hsqldb:mem:mymemdb");
    conf.set(JDBCDriverConfConstants.JDBC_USER, "SA");
    conf.set(JDBCDriverConfConstants.JDBC_PASSWORD, "");
    final DataSourceConnectionProvider cp = new DataSourceConnectionProvider();
    int numThreads = 50;
    Thread[] threads = new Thread[numThreads];
    final AtomicInteger passed = new AtomicInteger(0);
    final Semaphore sem = new Semaphore(1);
    for (int i = 0; i < numThreads; i++) {
        final int thid = i;
        threads[thid] = new Thread(new Runnable() {

            @Override
            public void run() {
                Connection conn = null;
                Statement st = null;
                try {
                    conn = cp.getConnection(conf);
                    Assert.assertNotNull(conn);
                    // Make sure the connection is usable
                    st = conn.createStatement();
                    Assert.assertNotNull(st);
                    passed.incrementAndGet();
                } catch (SQLException e) {
                    log.error("error getting connection to db!", e);
                } finally {
                    if (st != null) {
                        try {
                            st.close();
                        } catch (SQLException e) {
                            log.error("Encountered SQL ecxception", e);
                        }
                    }
                    if (conn != null) {
                        try {
                            conn.close();
                        } catch (SQLException e) {
                            log.error("Encountered SQL exception", e);
                        }
                    }
                }
            }
        });
        threads[thid].start();
    }
    for (Thread t : threads) {
        t.join();
    }
    cp.close();
    Assert.assertEquals(passed.get(), numThreads);
}

/**
 * Test get connection timeout.
 *
 * @throws Exception the exception
 */
@Test
public void testGetConnectionTimeout() throws Exception {
    final Configuration conf = new Configuration();
    conf.set(JDBCDriverConfConstants.JDBC_DRIVER_CLASS, "org.hsqldb.jdbc.JDBCDriver");
    conf.set(JDBCDriverConfConstants.JDBC_DB_URI, "jdbc:hsqldb:mem:mymemdb2");
    conf.set(JDBCDriverConfConstants.JDBC_USER, "SA");
    conf.set(JDBCDriverConfConstants.JDBC_PASSWORD, "");
    // Set a low timeout
    conf.setInt(JDBC_GET_CONNECTION_TIMEOUT.getConfigKey(), 1000);
    final int MAX_CONNECTIONS = 3;
    conf.setInt(JDBC_POOL_MAX_SIZE.getConfigKey(), MAX_CONNECTIONS);
    final DataSourceConnectionProvider cp = new DataSourceConnectionProvider();
    Connection[] connections = new Connection[MAX_CONNECTIONS + 1];
    for (int i = 0; i < MAX_CONNECTIONS + 1; i++) {
        // Last call should throw sql exception
        try {
            connections[i] = cp.getConnection(conf);
            if (i == MAX_CONNECTIONS) {
                fail("Expected last get connection to fail because of timeout");
            }
        } catch (SQLException sqlEx) {
            if (i != MAX_CONNECTIONS) {
                log.error("Unexpected getConnection error", sqlEx);
            }
            assertEquals(i, MAX_CONNECTIONS, "Failed before last getConnection call: " + sqlEx.getMessage());
        }
    }
    for (Connection c : connections) {
        if (c != null) {
            c.close();
        }
    }
}

