    Response response = lens.exec("get", QueryURL.PREPAREDQUERY_URL + "/" + queryPrepareHandle.toString(), servLens, null, query);
    AssertUtil.assertSucceededResponse(response);
    logger.info("Modifying PreparedQuery conf");
    LensConf lensConf = new LensConf();
    lensConf.addProperty(LensConfConstants.RESULT_SET_PARENT_DIR, "hdfs://lens-test:8020/tmp/lensreports");
    FormBuilder formData = new FormBuilder();
    formData.add("sessionid", sessionHandleString);
    formData.getForm().bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("conf").fileName("conf").build(), lensConf, MediaType.APPLICATION_XML_TYPE));
    response = lens.exec("put", QueryURL.PREPAREDQUERY_URL + "/" + queryPrepareHandle.toString(), servLens, null, null, MediaType.MULTIPART_FORM_DATA_TYPE, MediaType.APPLICATION_XML, formData.getForm());
    AssertUtil.assertSucceededResponse(response);
    logger.info("Get Should be Successful");
    response = lens.exec("get", QueryURL.PREPAREDQUERY_URL + "/" + queryPrepareHandle.toString(), servLens, null, query);
    AssertUtil.assertSucceededResponse(response);
    LensPreparedQuery gq = response.readEntity(new GenericType<LensPreparedQuery>() {
    });
    logger.info("Modified Conf : " + gq.getConf().getProperties().get("lens.query.result.parent.dir"));
    Assert.assertEquals(gq.getConf().getProperties().get(LensConfConstants.RESULT_SET_PARENT_DIR), "hdfs://lens-test:8020/tmp/lensreports", "Update on Prepared Query Failed!!");
}

