    try {
        createDimTable(table, mediaType);
        XStorageTableElement sTbl = createStorageTblElement("test2", table, "DAILY");
        APIResult result = target().path("metastore/dimtables").path(table).path("/storages").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XStorageTableElement>>(cubeObjectFactory.createXStorageTableElement(sTbl)) {
        }, mediaType), APIResult.class);
        assertSuccess(result);
        StringList storages = target().path("metastore").path("dimtables").path(table).path("storages").queryParam("sessionid", lensSessionId).request(mediaType).get(StringList.class);
        assertEquals(storages.getElements().size(), 2);
        assertTrue(storages.getElements().contains("test"), "Got " + storages.getElements().toString());
        assertTrue(storages.getElements().contains("test2"), "Got " + storages.getElements().toString());
        // Check get table also contains the storage
        JAXBElement<XDimensionTable> dt = target().path("metastore/dimtables").path(table).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XDimensionTable>>() {
        });
        XDimensionTable dimTable = dt.getValue();
        CubeDimensionTable cdim = JAXBUtils.cubeDimTableFromDimTable(dimTable);
        assertTrue(cdim.getStorages().contains("test"));
        assertTrue(cdim.getStorages().contains("test2"));
        assertEquals(cdim.getSnapshotDumpPeriods().get("test2"), DAILY);
        assertEquals(cdim.getSnapshotDumpPeriods().get("test"), HOURLY);
        result = target().path("metastore/dimtables/").path(table).path("storages").path("test").queryParam("sessionid", lensSessionId).request(mediaType).delete(APIResult.class);
        assertSuccess(result);
