        storages = target().path("metastore").path("dimtables").path(table).path("storages").queryParam("sessionid", lensSessionId).request(mediaType).get(StringList.class);
        assertEquals(storages.getElements().size(), 2);
        assertTrue(storages.getElements().contains("test2"));
        assertTrue(storages.getElements().contains("test3"));
        // Check get table also contains the storage
        dt = target().path("metastore/dimtables").path(table).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XDimensionTable>>() {
        });
