    try {
        XSegmentation seg = createSegmentation(segname);
        APIResult result = target().path("metastore").path("segmentations").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XSegmentation>>(cubeObjectFactory.createXSegmentation(seg)) {
        }, mediaType), APIResult.class);
        assertSuccess(result);
        // Get all segmentations, this should contain the segmentation created earlier
        StringList segNames = target().path("metastore/segmentations").queryParam("sessionid", lensSessionId).request(mediaType).get(StringList.class);
        assertTrue(segNames.getElements().contains(segname.toLowerCase()));
        // Get the created segmentation
        JAXBElement<XSegmentation> gotSegmentation = target().path("metastore/segmentations").path(segname).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XSegmentation>>() {
        });
        XSegmentation gotSeg = gotSegmentation.getValue();
        assertTrue(gotSeg.getName().equalsIgnoreCase(segname));
        assertEquals(gotSeg.getWeight(), 10.0);
        Segmentation cs = JAXBUtils.segmentationFromXSegmentation(seg);
        // Check for segemnts
        boolean foundCube1 = false;
        for (Segment cube : cs.getSegments()) {
            if (cube.getName().equalsIgnoreCase("cube1") && cube.getProperties().get("prop_key1").equals("prop_val1")) {
                foundCube1 = true;
                break;
            }
        }
        assertTrue(foundCube1);
        assertEquals(cs.getProperties().get("foo"), "bar");
        // update segmentation
        XSegmentation update = JAXBUtils.xsegmentationFromSegmentation(cs);
        XSegments cubes = new XSegments();
        XSegment c1 = cubeObjectFactory.createXSegment();
        c1.setCubeName("cube11");
        XSegment c2 = cubeObjectFactory.createXSegment();
        c2.setCubeName("cube22");
        cubes.getSegment().add(c1);
        cubes.getSegment().add(c2);
        update.setWeight(20.0);
        update.setSegements(cubes);
        result = target().path("metastore").path("segmentations").path(segname).queryParam("sessionid", lensSessionId).request(mediaType).put(Entity.entity(new GenericEntity<JAXBElement<XSegmentation>>(cubeObjectFactory.createXSegmentation(update)) {
