        JAXBElement<XSegmentation> gotUpdatedSeg = target().path("metastore/segmentations").path(segname).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XSegmentation>>() {
        });
        XSegmentation gotUpSeg = gotUpdatedSeg.getValue();
        Segmentation usg = JAXBUtils.segmentationFromXSegmentation(gotUpSeg);
        assertEquals(usg.getSegments().size(), 2);
        for (Segment segmnt : usg.getSegments()) {
            assertTrue(segmnt.getName().equals("cube11") || segmnt.getName().equals("cube22"));
        }
        // Finally, drop the segmentation
        result = target().path("metastore").path("segmentations").path(segname).queryParam("sessionid", lensSessionId).request(mediaType).delete(APIResult.class);
        assertSuccess(result);
        // Drop again, this time it should give a 404
        try {
            target().path("metastore").path("segmentations").path(segname).queryParam("cascade", "true").queryParam("sessionid", lensSessionId).request(mediaType).delete(APIResult.class);
            fail("Expected 404");
        } catch (NotFoundException nfe) {
            // PASS
        }
    } finally {
        setCurrentDatabase(prevDb, mediaType);
        dropDatabase(DB, mediaType);
    }
}

@Test(dataProvider = "mediaTypeData")
public void testCreateFactTableWithMultipleUpdatePeriods(MediaType mediaType) throws Exception {
    final String table = "testCreateFactTableWithMultipleUpdatePeriods";
    String prevDb = getCurrentDatabase(mediaType);
    final String DB = dbPFX + "testCreateFactTableWithMultipleUpdatePeriods_DB" + mediaType.getSubtype();
    createDatabase(DB, mediaType);
    setCurrentDatabase(DB, mediaType);
    createStorage("S1", mediaType);
    try {
        final XCube cube = createTestCube("testCube");
        target().path("metastore").path("cubes").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XCube>>(cubeObjectFactory.createXCube(cube)) {
        }, mediaType), APIResult.class);
        XFactTable f = createFactTable(table);
        String[] tables = new String[] { "testTable1", "testTable2", "testTable3" };
        String[] updatePeriods = new String[] { "HOURLY", "DAILY", "MONTHLY" };
        f.getStorageTables().getStorageTable().add(createStorageTblWithMultipleTableDescriptors("S1", tables, updatePeriods));
        APIResult result = target().path("metastore").path("facts").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XFact>>(cubeObjectFactory.createXFact(f)) {
        }, mediaType), APIResult.class);
        assertSuccess(result);
        StringList factNames = target().path("metastore/facts").queryParam("sessionid", lensSessionId).request(mediaType).get(StringList.class);
        assertTrue(factNames.getElements().contains(table.toLowerCase()));
        // Get the created tables
        JAXBElement<XFact> gotFactElement = target().path("metastore/facts").path(table).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XFact>>() {
        });
        XFactTable gotFact = (XFactTable) gotFactElement.getValue();
        assertTrue(gotFact.getName().equalsIgnoreCase(table));
        assertEquals(gotFact.getWeight(), 10.0);
        // Check for the created tables per update period.
        List<XUpdatePeriodTableDescriptor> updatePeriodTableDescriptor = gotFact.getStorageTables().getStorageTable().get(0).getUpdatePeriods().getUpdatePeriodTableDescriptor();
        assertEquals(updatePeriodTableDescriptor.size(), 3);
        CubeFactTable cf = JAXBUtils.cubeFactFromFactTable(gotFact);
        Map<UpdatePeriod, String> updatePeriodTablePrefixMap = cf.getStoragePrefixUpdatePeriodMap().get("S1");
        for (Map.Entry entry : updatePeriodTablePrefixMap.entrySet()) {
            assertEquals(entry.getValue(), entry.getKey() + "_S1");
        }
        // Do some changes to test update
        cf.alterWeight(20.0);
        cf.alterColumn(new FieldSchema("c2", "double", "changed to double"));
        XFactTable update = JAXBUtils.factTableFromCubeFactTable(cf);
        XStorageTableElement s1Tbl = createStorageTblWithMultipleTableDescriptors("S1", new String[] { tables[0], tables[1] }, new String[] { updatePeriods[0], updatePeriods[1] });
        update.getStorageTables().getStorageTable().add(s1Tbl);
        // Update
        result = target().path("metastore").path("facts").path(table).queryParam("sessionid", lensSessionId).request(mediaType).put(Entity.entity(new GenericEntity<JAXBElement<XFact>>(cubeObjectFactory.createXFact(update)) {
        }, mediaType), APIResult.class);
        assertSuccess(result);
        // Get the updated table
        gotFactElement = target().path("metastore/facts").path(table).queryParam("sessionid", lensSessionId).request(mediaType).get(new GenericType<JAXBElement<XFact>>() {
        });
        gotFact = (XFactTable) gotFactElement.getValue();
        CubeFactTable ucf = JAXBUtils.cubeFactFromFactTable(gotFact);
        assertEquals(ucf.weight(), 20.0);
        assertTrue(ucf.getUpdatePeriods().get("S1").contains(HOURLY));
        assertTrue(ucf.getUpdatePeriods().get("S1").contains(DAILY));
        assertFalse(ucf.getUpdatePeriods().get("S1").contains(MONTHLY));
        // Add partitions
        final Date partDate = new Date();
        XPartition xp = createPartition(table, partDate);
        APIResult partAddResult = target().path("metastore/facts/").path(table).path("storages/S1/partition").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XPartition>>(cubeObjectFactory.createXPartition(xp)) {
        }, mediaType), APIResult.class);
        assertSuccess(partAddResult);
        // add same should fail
        partAddResult = target().path("metastore/facts/").path(table).path("storages/S1/partition").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XPartition>>(cubeObjectFactory.createXPartition(xp)) {
        }, mediaType), APIResult.class);
        assertEquals(partAddResult.getStatus(), Status.FAILED);
        xp.setLocation(xp.getLocation() + "/a/b/c");
        APIResult partUpdateResult = target().path("metastore/facts/").path(table).path("storages/S1/partition").queryParam("sessionid", lensSessionId).request(mediaType).put(Entity.entity(new GenericEntity<JAXBElement<XPartition>>(cubeObjectFactory.createXPartition(xp)) {
        }, mediaType), APIResult.class);
        assertSuccess(partUpdateResult);
        JAXBElement<XPartitionList> partitionsElement = target().path("metastore/facts").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).queryParam("filter", "dt='" + HOURLY.format(partDate) + "'").request(mediaType).get(new GenericType<JAXBElement<XPartitionList>>() {
        });
        //Getting partitions without filter will throw an error.
        Response res = target().path("metastore/facts").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).request(mediaType).get();
        assertEquals(res.getStatus(), 400);
        assertEquals(res.readEntity(String.class), "Partition filter can not be null or empty");
        XPartitionList partitions = partitionsElement.getValue();
        assertNotNull(partitions);
        assertEquals(partitions.getPartition().size(), 1);
        XPartition readPartition = partitions.getPartition().get(0);
        assertEquals(readPartition.getLocation(), xp.getLocation());
        assertEquals(readPartition.getTimePartitionSpec(), xp.getTimePartitionSpec());
        assertEquals(readPartition.getNonTimePartitionSpec(), xp.getNonTimePartitionSpec());
        assertNotNull(readPartition.getFullPartitionSpec());
        XTimePartSpecElement timePartSpec = readPartition.getTimePartitionSpec().getPartSpecElement().iterator().next();
        XPartSpecElement fullPartSpec = readPartition.getFullPartitionSpec().getPartSpecElement().iterator().next();
        assertEquals(timePartSpec.getKey(), fullPartSpec.getKey());
        assertEquals(UpdatePeriod.valueOf(xp.getUpdatePeriod().name()).format(JAXBUtils.getDateFromXML(timePartSpec.getValue())), fullPartSpec.getValue());
        DateTime date = target().path("metastore/cubes").path("testCube").path("latestdate").queryParam("timeDimension", "dt").queryParam("sessionid", lensSessionId).request(mediaType).get(DateTime.class);
        partDate.setMinutes(0);
        partDate.setSeconds(0);
        partDate.setTime(partDate.getTime() - partDate.getTime() % 1000);
        assertEquals(date.getDate(), partDate);
        // add two partitions, one of them already added. result should be partial
        XPartitionList parts = new XPartitionList();
        parts.getPartition().add(xp);
        parts.getPartition().add(createPartition(table, DateUtils.addHours(partDate, 1)));
        partAddResult = target().path("metastore/facts/").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).request(mediaType).post(Entity.entity(new GenericEntity<JAXBElement<XPartitionList>>(cubeObjectFactory.createXPartitionList(parts)) {
        }, mediaType), APIResult.class);
        assertEquals(partAddResult.getStatus(), Status.PARTIAL);
        // Drop the partitions
        APIResult dropResult = target().path("metastore/facts").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).request(mediaType).delete(APIResult.class);
        assertSuccess(dropResult);
        // Verify partition was dropped
        partitionsElement = target().path("metastore/facts").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).queryParam("filter", "dt='" + HOURLY.format(partDate) + "'").request(mediaType).get(new GenericType<JAXBElement<XPartitionList>>() {
        });
        partitions = partitionsElement.getValue();
        assertNotNull(partitions);
        assertEquals(partitions.getPartition().size(), 0);
        // add null in batch
        Response resp = target().path("metastore/facts/").path(table).path("storages/S1/partitions").queryParam("sessionid", lensSessionId).request(mediaType).post(null);
        Assert.assertEquals(resp.getStatus(), 400);
        // Drop the cube
        WebTarget target = target().path("metastore").path("cubes").path("testCube");
        result = target.queryParam("sessionid", lensSessionId).request(mediaType).delete(APIResult.class);
        assertSuccess(result);
    } finally {
        setCurrentDatabase(prevDb, mediaType);
        dropDatabase(DB, mediaType);
    }
}

