        assertSuccess(partAddResult);
        // End: Setup
        // Begin: Test Execution
        // Get latest date for Cube using timeDimOnlyPresentInPartitionOfFact1
        DateTime retrievedLatestDate = target().path("metastore/cubes").path(cubeName).path("latestdate").queryParam("timeDimension", timeDimOnlyPresentInPartitionOfFact1).queryParam("sessionid", lensSessionId).request(mediaType).get(DateTime.class);
        // End: Test Execution
        // Begin: Verification
        assertEquals(retrievedLatestDate.getDate(), DateUtils.truncate(expectedLatestDate, Calendar.HOUR));
        // End: Verification
    } finally {
        // Cleanup
        setCurrentDatabase(prevDb, mediaType);
        dropDatabase(dbName, mediaType);
    }
}

