@Test(dataProvider = "success-tests")
public void testSuccessfulQuery(Boolean lensPersistence, Boolean driverPersistence, MediaType mt) throws InterruptedException, LensException {
    // successful query
    LensConf conf = getLensConf(LensConfConstants.QUERY_PERSISTENT_RESULT_SET, lensPersistence, LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, driverPersistence);
    String expectedKeywords;
    QueryHandle handle = launchAndWaitForQuery(conf, "select ID, IDSTR from " + TEST_TABLE, Status.SUCCESSFUL, mt);
    if (lensPersistence || driverPersistence) {
        QueryResult result = getLensQueryResult(target(), lensSessionId, handle, mt);
        expectedKeywords = result.toPrettyString();
    } else {
        QueryContext context = queryService.getQueryContext(handle);
        long creationTime = ((InMemoryResultSet) (context.getSelectedDriver().fetchResultSet(context))).getCreationTime();
        long inMemoryResultsetTTLSecs = LensServerConf.getHiveConf().getInt(LensConfConstants.INMEMORY_RESULT_SET_TTL_SECS, LensConfConstants.DEFAULT_INMEMORY_RESULT_SET_TTL_SECS);
        expectedKeywords = QueryEndNotifier.RESULT_AVAILABLE_UNTIL_MSG + QueryEndNotifier.MESSAGE_DATE_FORMATTER.print(creationTime + inMemoryResultsetTTLSecs);
        //Reading it so that query can be purged
        getLensQueryResultAsString(target(), lensSessionId, handle, mt);
    }
    WiserMessage message = getMessage();
    assertKeywordsContains(message, handle, "Query SUCCESSFUL", expectedKeywords);
    if (lensPersistence) {
        assertKeywordsContains(message, new String[] { "Downloadable from", "httpresultset" });
        assertEquals(getLensQueryHttpResult(target(), lensSessionId, handle).getStatus(), Response.Status.OK.getStatusCode());
    } else {
        assertEquals(getLensQueryHttpResult(target(), lensSessionId, handle).getStatus(), Response.Status.NOT_FOUND.getStatusCode());
    }
}

@Test(dataProvider = "restartDataProvider", enabled = false)
public void testQueryAliveOnSessionClose(boolean restartBeforeFinish, boolean restartAfterFinish) throws LensException, InterruptedException {
    int numSessions = getSessionsOfFoo().size();
    MediaType mt = MediaType.APPLICATION_XML_TYPE;
    LensSessionHandle sessionHandle = getSession();
    QueryHandle queryHandle1 = RestAPITestUtil.executeAndGetHandle(target(), Optional.of(sessionHandle), Optional.of("select * from " + TEST_TABLE), Optional.of(conf), mt);
    QueryHandle queryHandle2 = RestAPITestUtil.executeAndGetHandle(target(), Optional.of(sessionHandle), Optional.of("select *  from " + TEST_TABLE), Optional.of(conf), mt);
    assertNotEquals(queryHandle1, queryHandle2);
    // Second query should be queued
    assertEquals(getQueryService().getQueryContext(queryHandle2).getStatus().getStatus(), QueryStatus.Status.QUEUED);
    closeSession(sessionHandle);
    // Session not 'truly' closed
    assertNotNull(getQueryService().getSession(sessionHandle));
    // Just 'marked' for closing
    assertTrue(getQueryService().getSession(sessionHandle).getLensSessionPersistInfo().isMarkedForClose());
    // Try submitting another query in this so called "inactive" session
    Response response = RestAPITestUtil.postQuery(target(), Optional.of(sessionHandle), Optional.of("select * from " + TEST_TABLE), Optional.of("execute"), mt);
    assertEquals(response.getStatus(), 410);
    LensAPIResult apiResult = response.readEntity(LensAPIResult.class);
    assertEquals(apiResult.getErrorCode(), 2005);
    // Should be able to open another session, since max session per user is 1 and this session is closed
    LensSessionHandle sessionHandle1 = getSession();
    assertNotNull(sessionHandle1);
    if (restartBeforeFinish) {
        customRestartLensServer();
    }
    assertTrue(getQueryService().getSession(sessionHandle).getLensSessionPersistInfo().isMarkedForClose());
    assertTrue(getQueryService().getSession(sessionHandle).isActive());
    for (QueryHandle handle : Arrays.asList(queryHandle2, queryHandle1)) {
        RestAPITestUtil.waitForQueryToFinish(target(), lensSessionId, handle, QueryStatus.Status.SUCCESSFUL, mt);
    }
    // Session should not be active
    assertFalse(getQueryService().getSession(sessionHandle).isActive());
    if (restartAfterFinish) {
        customRestartLensServer();
    }
    assertTrue(getQueryService().getSession(sessionHandle).getLensSessionPersistInfo().isMarkedForClose());
    // Now, session is not active anymore
    assertFalse(getQueryService().getSession(sessionHandle).isActive());
    // It should not be possible to submit queries now
    response = RestAPITestUtil.postQuery(target(), Optional.of(sessionHandle), Optional.of("select * from " + TEST_TABLE), Optional.of("execute"), Optional.of(conf), mt);
    assertEquals(response.getStatus(), 410);
    apiResult = response.readEntity(LensAPIResult.class);
    assertEquals(apiResult.getErrorCode(), LensServerErrorCode.SESSION_CLOSED.getLensErrorInfo().getErrorCode());
    getSessionService().cleanupIdleSessions();
    assertTrue(getSessionsOfFoo().size() - numSessions <= 2);
}

@Test
public void testSessionExpiryWithActiveOperation() throws Exception {
    LensSessionHandle oldSession = getSession();
    assertTrue(sessionService.getSession(oldSession).isActive());
    restartLensServerWithLowerExpiry();
    assertFalse(sessionService.getSession(oldSession).isActive());
    // create a new session and launch a query
    LensSessionHandle sessionHandle = getSession();
    LensSessionImpl session = sessionService.getSession(sessionHandle);
    QueryHandle handle = RestAPITestUtil.executeAndGetHandle(target(), Optional.of(sessionHandle), Optional.of("select * from " + TEST_TABLE), Optional.of(conf), defaultMT);
    assertTrue(session.isActive());
    session.setLastAccessTime(session.getLastAccessTime() - 2000 * getServerConf().getLong(LensConfConstants.SESSION_TIMEOUT_SECONDS, LensConfConstants.SESSION_TIMEOUT_SECONDS_DEFAULT));
    assertTrue(session.isActive());
    assertFalse(session.isMarkedForClose());
    LensSessionHandle sessionHandle2 = getSession();
    LensQuery ctx = RestAPITestUtil.getLensQuery(target(), sessionHandle2, handle, defaultMT);
    while (!ctx.getStatus().finished()) {
        ctx = RestAPITestUtil.getLensQuery(target(), sessionHandle2, handle, defaultMT);
        Thread.sleep(1000);
        sessionHandle2 = getSession();
    }
    assertEquals(ctx.getStatus().getStatus(), QueryStatus.Status.SUCCESSFUL, String.valueOf(ctx));
    assertFalse(session.isActive());
    assertFalse(session.isMarkedForClose());
    // run the expiry thread
    sessionService.getSessionExpiryRunnable().run();
    try {
        sessionService.getSession(sessionHandle);
        // should throw exception since session should be expired by now
        fail("Expected get session to fail for session " + sessionHandle.getPublicId());
    } catch (Exception e) {
        // pass
    }
    try {
        sessionService.getSession(oldSession);
        // should throw exception since session should be expired by now
        fail("Expected get session to fail for session " + oldSession.getPublicId());
    } catch (Exception e) {
        // pass
    }
    restartLensServer();
    lensSessionId = getSession();
}

