/**
 * Test execute async.
 *
 * @throws InterruptedException the interrupted exception
 * @throws IOException          Signals that an I/O exception has occurred.
 */
@Test(dataProvider = "mediaTypeData")
public void testExecuteAsync(MediaType mt) throws InterruptedException, IOException, LensException {
    // test post execute op
    final WebTarget target = target().path("queryapi/queries");
    long queuedQueries = metricsSvc.getQueuedQueries();
    long runningQueries = metricsSvc.getRunningQueries();
    final FormDataMultiPart mp = new FormDataMultiPart();
    mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("sessionid").build(), lensSessionId, mt));
    mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("query").build(), "select ID, IDSTR from " + TEST_TABLE));
    mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("operation").build(), "execute"));
    mp.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("conf").fileName("conf").build(), new LensConf(), mt));
    final QueryHandle handle = target.request(mt).post(Entity.entity(mp, MediaType.MULTIPART_FORM_DATA_TYPE), new GenericType<LensAPIResult<QueryHandle>>() {
    }).getData();
    assertNotNull(handle);
    QueryContext ctx = queryService.getUpdatedQueryContext(lensSessionId, handle);
    assertEquals(ctx.getSelectedDriverConf().get(KEY_POST_SELECT), VALUE_POST_SELECT);
    // Get query
    LensQuery lensQuery = target.path(handle.toString()).queryParam("sessionid", lensSessionId).request(mt).get(LensQuery.class);
    assertTrue(lensQuery.getStatus().getStatus().equals(Status.QUEUED) || lensQuery.getStatus().getStatus().equals(Status.LAUNCHED) || lensQuery.getStatus().getStatus().equals(Status.RUNNING) || lensQuery.getStatus().getStatus().equals(Status.SUCCESSFUL), lensQuery.getStatus().toString());
    // wait till the query finishes
    QueryStatus stat = lensQuery.getStatus();
    while (!stat.finished()) {
        lensQuery = target.path(handle.toString()).queryParam("sessionid", lensSessionId).request(mt).get(LensQuery.class);
        stat = lensQuery.getStatus();
        /* Commented and jira ticket raised for correction: https://issues.apache.org/jira/browse/LENS-683
      switch (stat.getStatus()) {
      case RUNNING:
        assertEquals(metricsSvc.getRunningQueries(), runningQueries + 1,
            "Asserting queries for " + ctx.getQueryHandle());
        break;
      case QUEUED:
        assertEquals(metricsSvc.getQueuedQueries(), queuedQueries + 1);
        break;
      default: // nothing
      }*/
        Thread.sleep(1000);
    }
    assertEquals(ctx.getSelectedDriverConf().get(KEY_PRE_LAUNCH), VALUE_PRE_LAUNCH);
    assertEquals(ctx.getSelectedDriverConf().get(PRE_REWRITE), PRE_REWRITE);
    assertEquals(ctx.getSelectedDriverConf().get(POST_REWRITE), POST_REWRITE);
    assertEquals(ctx.getSelectedDriverConf().get(PRE_ESTIMATE), PRE_ESTIMATE);
    assertEquals(ctx.getSelectedDriverConf().get(POST_ESTIMATE), POST_ESTIMATE);
    assertTrue(lensQuery.getSubmissionTime() > 0);
    assertTrue(lensQuery.getLaunchTime() > 0);
    assertTrue(lensQuery.getDriverStartTime() > 0);
    assertTrue(lensQuery.getDriverFinishTime() > 0);
    assertTrue(lensQuery.getFinishTime() > 0);
    ctx = queryService.getUpdatedQueryContext(lensSessionId, lensQuery.getQueryHandle());
    assertNotNull(ctx.getPhase1RewrittenQuery());
    //Since there is no rewriter in this test
    assertEquals(ctx.getPhase1RewrittenQuery(), ctx.getUserQuery());
    assertEquals(lensQuery.getStatus().getStatus(), QueryStatus.Status.SUCCESSFUL);
    validatePersistedResult(handle, target(), lensSessionId, new String[][] { { "ID", "INT" }, { "IDSTR", "STRING" } }, true, false, mt);
    // test cancel query
    final QueryHandle handle2 = target.request(mt).post(Entity.entity(mp, MediaType.MULTIPART_FORM_DATA_TYPE), new GenericType<LensAPIResult<QueryHandle>>() {
    }).getData();
    assertNotNull(handle2);
    APIResult result = target.path(handle2.toString()).queryParam("sessionid", lensSessionId).request(mt).delete(APIResult.class);
    // cancel would fail query is already successful
    LensQuery ctx2 = target.path(handle2.toString()).queryParam("sessionid", lensSessionId).request(mt).get(LensQuery.class);
    if (result.getStatus().equals(APIResult.Status.FAILED)) {
        assertEquals(ctx2.getStatus().getStatus(), QueryStatus.Status.SUCCESSFUL, "cancel failed without query having been succeeded");
    } else if (result.getStatus().equals(APIResult.Status.SUCCEEDED)) {
        assertEquals(ctx2.getStatus().getStatus(), QueryStatus.Status.CANCELED, "cancel succeeded but query wasn't cancelled");
    } else {
        fail("unexpected cancel status: " + result.getStatus());
    }
    // 1. Test http download end point and result path should be correct (when both driver and server persist)
    // 2. Test Fetch result should fail before query is marked successful
    log.info("Starting httpendpoint test");
    final FormDataMultiPart mp3 = new FormDataMultiPart();
    mp3.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("sessionid").build(), lensSessionId, mt));
    mp3.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("query").build(), "select ID, IDSTR from " + TEST_TABLE));
    mp3.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("operation").build(), "execute"));
    LensConf conf = new LensConf();
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_SET, "true");
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, "true");
    conf.addProperty(LensConfConstants.QUERY_OUTPUT_FORMATTER, DeferredPersistentResultFormatter.class.getName());
    // defer persistence for 5 secs
    conf.addProperty("deferPersistenceByMillis", 5000);
    mp3.bodyPart(new FormDataBodyPart(FormDataContentDisposition.name("conf").fileName("conf").build(), conf, mt));
    final QueryHandle handle3 = target.request(mt).post(Entity.entity(mp3, MediaType.MULTIPART_FORM_DATA_TYPE), new GenericType<LensAPIResult<QueryHandle>>() {
    }).getData();
    QueryContext ctx3 = queryService.getQueryContext(handle3);
    //Formatting is deferred so query will take time to finish
    assertFalse(ctx3.finished());
    try {
        queryService.fetchResultSet(lensSessionId, handle3, 0, 100);
        fail("client should not be allowed to fetch result before query finishes successfully");
    } catch (NotFoundException e) {
        // Expected. Ignore
    }
    waitForQueryToFinish(target(), lensSessionId, handle3, Status.SUCCESSFUL, mt);
    LensResultSet rs = queryService.getResultset(handle3);
    //check persisted result path
    String expectedPath = ctx3.getSelectedDriverConf().get(LensConfConstants.RESULT_SET_PARENT_DIR) + "/" + handle3.getHandleIdString() + ctx3.getConf().get(LensConfConstants.QUERY_OUTPUT_FILE_EXTN);
    assertTrue(((PersistentResultSet) rs).getOutputPath().endsWith(expectedPath), "Result Path " + ((PersistentResultSet) rs).getOutputPath() + " does not contain expected path: " + expectedPath);
    validateHttpEndPoint(target(), null, handle3, null);
}

